            EX("Worked example 2: monthly contributions", intro="A worker earns 150 000 FCFA a month. In a teaching example (rates invented for practice) the employee pays 4% of wages and the employer pays 8%. How much is paid into the fund each month in total?", steps=[
                S("Employee share", math=r"150\,000 \times \frac{4}{100} = 6\,000"),
                S("Employer share", math=r"150\,000 \times \frac{8}{100} = 12\,000"),
                S("Add them", math=r"6\,000 + 12\,000 = 18\,000"),
                S("State the answer", text="**18 000 FCFA** a month is paid into the fund in this invented example. Real rates are set by law: check the current rules."),
            ], check=r"150\,000 \times \frac{12}{100} = 18\,000"),
            TIP("Paper 1 and Paper 2 may ask you to name the institution, the kinds of benefit or the purpose of social security. Write 'protection against loss of income caused by risks' rather than 'money for workers'.", title="Exam link"),
